inp=[[1,9,1,9],[9,9,9,1],[1,1,4,1],[9,4,1,9],[1,1,1,4]]
out=[[4,1,1,1,1,1,1,4],[9,1,4,9,9,4,1,9],[1,4,1,1,1,1,4,1],[1,9,9,9,9,9,9,1],[9,1,9,1,1,9,1,9],[9,1,9,1,1,9,1,9],[1,9,9,9,9,9,9,1],[1,4,1,1,1,1,4,1],[9,1,4,9,9,4,1,9],[4,1,1,1,1,1,1,4],[4,1,1,1,1,1,1,4],[9,1,4,9,9,4,1,9],[1,4,1,1,1,1,4,1],[1,9,9,9,9,9,9,1],[9,1,9,1,1,9,1,9]]
from collections import defaultdict
patterns=defaultdict(list)
for r in range(5):
 for c in range(4): patterns[inp[r][c]].append(tuple(tuple(row[2*c:2*c+2]) for row in out[3*r:3*r+3]))
for k,v in patterns.items(): print(k, 'patterns:', *[str(x) for x in v],sep='\n')
